define("local_learningplans/view_reorder",["jquery","core/sortable_list"],(function($,SortableList){var init=function(listSelector,formSelector,inputSelector){var list=$(listSelector);var form=$(formSelector);var orderInput=$(inputSelector);if(!list.length||!form.length||!orderInput.length||list.children().length<2){return}var sortable=new SortableList(listSelector);sortable.getElementName=function(element){var name=element.attr("data-name")||$.trim(element.find(".learning-plan__course-name").text());return $.Deferred().resolve(name)};list.children().on(SortableList.EVENTS.DRAGSTART,(function(_,info){setTimeout((function(){$(".sortable-list-is-dragged").width(info.element.width())}),250)})).on(SortableList.EVENTS.DROP,(function(_,info){if(!info.positionChanged){return}var orderedIds=[];info.targetList.children().each((function(){var courseId=parseInt($(this).attr("data-courseid"),10);if(!isNaN(courseId)&&courseId>0){orderedIds.push(courseId)}}));if(!orderedIds.length){return}orderInput.val(orderedIds.join(","));form.trigger("submit")}))};return{init:init}}));
